#!/usr/bin/env python3
"""Produce offline HTML explorer from real generated synthetic fixtures, no network."""
from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parents[1]
read=lambda p:json.loads((ROOT/p).read_text())
source=read('data/source_registry.json')
examples={}
for feed in source:
 key=feed['source_key'];examples[key]={}
 for tenant in ['northstar','beacon']:
  p=ROOT/'data'/'raw'/key/(tenant+'.jsonl')
  examples[key][tenant]=[json.loads(l) for l in p.read_text().splitlines()[:4]]
features=read('data/feature_inventory.json')
conflicts=read('data/fixtures/conflict_manifest.json')
scenarios=[json.loads(l) for l in (ROOT/'data/evaluation/scenarios.jsonl').read_text().splitlines()[:40]]
tools=read('data/agent_tool_contracts.json')
tenants=read('data/tenants.json')
pack={'sources':source,'examples':examples,'features':features,'conflicts':conflicts,'scenarios':scenarios,'tools':tools,'tenants':tenants}
blob=json.dumps(pack,ensure_ascii=False).replace('</','<\\/')
page='''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enterprise IT Synthetic Data Explorer</title>
<style>
:root{color-scheme:dark;--b:#0a101c;--s:#121d2b;--s2:#172535;--line:#2c4053;--t:#edf4f7;--m:#a0b0c1;--a:#9ee7cb;--w:#e8ba87}*{box-sizing:border-box}body{margin:0;background:var(--b);color:var(--t);font-family:system-ui,-apple-system,Segoe UI,sans-serif;line-height:1.45}header{padding:28px max(20px,calc((100vw - 1300px)/2));border-bottom:1px solid var(--line);background:linear-gradient(110deg,#142537,#0a101c)}h1{margin:2px 0 8px;font-size:clamp(24px,3vw,37px);letter-spacing:-.04em}p{color:var(--m);margin:6px 0}.tag{font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--a)}.shell{max-width:1300px;margin:auto;padding:22px}nav{display:flex;flex-wrap:wrap;gap:7px;padding:0 0 18px}button,select,input{background:var(--s);border:1px solid var(--line);color:var(--t);border-radius:9px;padding:10px 13px;font:inherit}button{cursor:pointer}button.active{border-color:var(--a);background:#1a3434;color:var(--a)}input{min-width:170px;width:280px;max-width:100%}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:15px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin:19px 0 26px}.card,.panel{background:var(--s);border:1px solid var(--line);border-radius:13px;padding:17px}.card strong{font-size:24px;display:block}.card span{font-size:12px;color:var(--m)}.layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:15px}.sidebar{max-height:70vh;overflow:auto}.item{padding:10px 8px;border-bottom:1px solid var(--line);cursor:pointer;border-radius:5px}.item:hover,.item.sel{background:#203646}.item b{display:block;font-size:13px}.item small{color:var(--m)}.record{padding:12px 0;border-top:1px solid var(--line)}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;background:#090f17;border:1px solid #243747;border-radius:10px;padding:14px;margin:7px 0 0;color:#bde7d5}h3{margin:5px 0}h4{margin:10px 0 4px}aside{color:var(--w);font-size:12px;margin:12px 0}.pill{font-size:11px;color:var(--a);border:1px solid #285547;padding:3px 7px;border-radius:99px;white-space:nowrap}.feature{border-top:1px solid var(--line);padding:10px 0;display:flex;gap:12px;align-items:start;justify-content:space-between}.feature b{font-size:13px}.muted{font-size:12px;color:var(--m)}footer{font-size:12px;color:var(--m);padding:25px 0}#page{min-height:35vh}@media(max-width:830px){.cards{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}.sidebar{max-height:230px}header{padding:22px}.shell{padding:15px}}</style>
</head><body><header><div class="tag">Agentic Bakery Pro · Independent demo fixture</div><h1>Enterprise IT Data Explorer</h1><p>Two fictional organisations • independent source systems • contradictory evidence • realistic agent use cases</p><p>Offline preview only. Real source records and complete datasets are in the accompanying ZIP.</p></header><main class="shell"><div class="cards"><div class="card"><strong>47</strong><span>Independent source feeds</span></div><div class="card"><strong>114</strong><span>Enterprise capabilities</span></div><div class="card"><strong>160</strong><span>Evaluation variants</span></div><div class="card"><strong>20</strong><span>Deliberate cross-source conflicts</span></div></div><nav id="tabs"></nav><div id="page"></div><footer>All identities and customer data are synthetic; mock integrations are not official API exports. The 160 scenarios have not been executed against any LLM.</footer></main>
<script>const DATA=__BLOB__;const tabs=['Source feeds','Features','Scenario library','Contradictions','Agent tools'];let tab=tabs[0],selected=DATA.sources[0].source_key,tenant='northstar',term='';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const bold=s=>'<b>'+esc(s)+'</b>';function nav(){ $('#tabs').innerHTML=tabs.map(x=>`<button class="${tab===x?'active':''}" data-tab="${esc(x)}">${esc(x)}</button>`).join(''); document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{tab=e.dataset.tab;term='';nav();render()})}function selectors(){return `<div class="controls"><input id="search" placeholder="Search current view..." value="${esc(term)}" oninput="term=this.value;render()"/><select id="tenant" onchange="tenant=this.value;render()"><option value="northstar" ${tenant==='northstar'?'selected':''}>Northstar Technologies</option><option value="beacon" ${tenant==='beacon'?'selected':''}>Beacon Retail Group</option></select></div>`}function render(){let pg=$('#page');const match=x=>JSON.stringify(x).toLowerCase().includes(term.toLowerCase());if(tab==='Source feeds'){let list=DATA.sources.filter(match);if(!list.some(x=>x.source_key===selected)&&list.length)selected=list[0].source_key;let s=DATA.sources.find(x=>x.source_key===selected);pg.innerHTML=selectors()+`<div class="layout"><div class="panel sidebar">${list.map(x=>`<div class="item ${selected===x.source_key?'sel':''}" data-source="${esc(x.source_key)}"><b>${esc(x.source_key)}</b><small>${x.records} records · ${esc(x.source_owner)}</small></div>`).join('')}</div><section class="panel"><span class="tag">Source preview</span><h3>${esc(s?.source_key||'No matching source')}</h3><p>${esc(s?.source_system||'')} · ${esc(s?.update_cadence||'')} · Classification: ${esc(s?.sensitivity||'')}</p><aside>Showing up to four original records from this source and selected tenant. Contradictory records are intentionally not reconciled here.</aside>${(DATA.examples[selected]?.[tenant]||[]).map((r,i)=>`<div class="record"><div class="muted">SOURCE RECORD ${i+1}</div><pre>${esc(JSON.stringify(r,null,2))}</pre></div>`).join('')||'<p>No source records</p>'}</section></div>`;document.querySelectorAll('[data-source]').forEach(e=>e.onclick=()=>{selected=e.dataset.source;render()});}
 else if(tab==='Features'){let arr=DATA.features.filter(match);pg.innerHTML=selectors()+`<div class="panel"><h3>${arr.length} matching enterprise capabilities</h3><aside>Capability inventory is a specification, not a completed app implementation checklist.</aside>${arr.map(f=>`<div class="feature"><div>${bold(f.capability)}<div class="muted">${esc(f.feature_id)} · ${esc(f.module)} · ${esc(f.user_roles)}</div><div class="muted">${esc(f.rule_or_failure_condition)}</div></div><span class="pill">${esc(f.status==='fixture_supported'?'Data supported':'To build')}</span></div>`).join('')}</div>`}
 else if(tab==='Scenario library'){let arr=DATA.scenarios.filter(x=>x.tenant_id===tenant&&match(x));pg.innerHTML=selectors()+`<div class="panel"><h3>${arr.length} reference scenarios</h3><aside>40 unique base scenarios (subset filtered by selected tenant), expanded to 160 variants in JSONL. Expected outcomes stay in the offline oracle.</aside>${arr.map(s=>`<div class="feature"><div>${bold(s.title)}<div class="muted">${esc(s.case_id)} · ${esc(s.actor_role)} · ${esc(s.category)}</div><p>${esc(s.conversation[0].content)}</p><small class="muted">Sources: ${esc(s.relevant_sources.join(', '))}</small></div></div>`).join('')}</div>`}
 else if(tab==='Contradictions'){let arr=DATA.conflicts.filter(match);pg.innerHTML=selectors()+`<div class="panel"><h3>${arr.length} documented conflicts</h3>${arr.map(s=>`<div class="feature"><div>${bold(s.conflict_id+' · '+s.sources)}<div class="muted">${esc(s.record_reference)}</div><p>${esc(s.description)}</p></div><span class="pill">${esc(s.priority)}</span></div>`).join('')}</div>`}
 else {let arr=DATA.tools.filter(match);pg.innerHTML=selectors()+`<div class="panel"><h3>${arr.length} candidate agent tools</h3><aside>Endpoint present means route template exists in mock API. No real AWS MCP gateway is configured by this file.</aside>${arr.map(t=>`<div class="feature"><div>${bold(t.name)}<div class="muted">${esc(t.domain)} · ${esc(t.action_class)} · ${esc(t.required_authorisation)}</div><p>${esc(t.mock_api_endpoint||'Proposed only — not implemented')}</p></div><span class="pill">${t.endpoint_implemented?'Route':'To build'}</span></div>`).join('')}</div>`}}
nav();render();</script></body></html>'''
(ROOT/'explorer.html').write_text(page.replace('__BLOB__',blob),encoding='utf8')
print('explorer.html', (ROOT/'explorer.html').stat().st_size,'bytes')
